
import base64, io, os, subprocess, sys, tarfile, glob, time
CODE = ""
os.makedirs("/kaggle/working/src", exist_ok=True)
tarfile.open(fileobj=io.BytesIO(base64.b64decode(CODE))).extractall("/kaggle/working/src")
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "polars==1.44.2", "rapidfuzz==3.14.5",
                "sparse_dot_topn==1.2.0", "unidecode", "xgboost==3.1.2"], check=True)

def find(name):
    """Directory under /kaggle/input that contains `name`."""
    for root, _, files in os.walk("/kaggle/input"):
        if name in files:
            return root
    return None

env = dict(os.environ, PYTHONUNBUFFERED="1", BER_THREADS="4",
           BER_CACHE=find("train_s1_norm.parquet"),
           BER_OUTPUTS="/kaggle/working/outputs", BER_OUTPUT="/kaggle/working/output")
import shutil
os.makedirs("/kaggle/working/work", exist_ok=True)
src_dir = find("test_cheap_France_0.parquet")
for f in os.listdir(src_dir):
    shutil.copy(os.path.join(src_dir, f), "/kaggle/working/work")
env["BER_WORK"] = "/kaggle/working/work"; env["BER_MODELS"] = find("prune0.json"); env["USE_TF"] = "0"
env["BER_KKEEP"] = "999"; env["BER_RKEEP"] = "999"; env["BER_NCHUNK"] = "8"; env["BER_SUB"] = "15"; env["BER_CE_PAIRS"] = "3000000"; env["BER_LR"] = "0.1"; env["BER_ROUNDS"] = "3000"; env["BER_TRIMODE"] = "rare"; env["BER_KREVSP"] = "25"; env["BER_SIB"] = "1"; env["BER_DROPS1"] = "0.187"; env["BER_SUB"] = "30"; env["BER_HOLD"] = "80"; env["BER_FR_ADAPT"] = "1"; env["BER_ADAPT_N"] = "40000"; 
print("env", {k: v for k, v in env.items() if k.startswith("BER_")}, flush=True)
os.system("nvidia-smi -L; free -g; nproc")
for stage in ['features_test', 'infer']:
    t = time.time()
    r = subprocess.run([sys.executable, "-u", "/kaggle/working/src/run_all.py", "--only", stage], env=env)
    print("STAGE", stage, "exit", r.returncode, "secs", int(time.time() - t), flush=True)
    if r.returncode != 0:
        sys.exit(r.returncode)
